import React from 'react';

const DonorCard = ({ donor, onClick }) => {
    // Define better background and border styling based on status
    let bgColorClass = '';
    let borderColorClass = '';

    if (donor.status === 'pending') {
        bgColorClass = 'bg-gradient-to-r from-yellow-50 to-amber-50';
        borderColorClass = 'border-l-4 border-yellow-400';
    } else if (donor.status === 'sending') {
        bgColorClass = 'bg-gradient-to-r from-blue-50 to-sky-50';
        borderColorClass = 'border-l-4 border-blue-400';
    } else {
        bgColorClass = 'bg-gradient-to-r from-green-50 to-emerald-50';
        borderColorClass = 'border-l-4 border-green-400';
    }

    // Just enhance the main container styling, keep everything else the same
    return (
        <div
            className={`p-4 mb-4 rounded-lg shadow-sm hover:shadow-md transition-all duration-200 ${bgColorClass} ${borderColorClass}`}
            onClick={onClick}
        >
            {/* Keep original content structure exactly the same */}
            <div className="flex justify-between items-center">
                <div>
                    <h3 className="font-medium text-gray-800">{donor.firstName} {donor.lastName}</h3>
                    <p className="text-sm text-gray-600">{donor.whatsappNumber}</p>
                    <div className="flex mt-2 gap-2">
                        <span className={`text-xs px-2 py-1 rounded-full ${donor.type === 'sheep' ? 'bg-sky-100 text-sky-800 border border-sky-300' : 'bg-purple-100 text-purple-800 border border-purple-300'}`}>
                            {donor.type === 'sheep' ? 'Sheep' : 'Cow (1/7 share)'}
                        </span>
                        <span className={`text-xs px-2 py-1 rounded-full ${donor.status === 'pending' ? 'bg-yellow-100 text-yellow-800 border border-yellow-300' : donor.status === 'sending' ? 'bg-blue-100 text-blue-800 border border-blue-300' : 'bg-green-100 text-green-800 border border-green-300'}`}>
                            {donor.status === 'pending' ? 'Pending' : donor.status === 'sending' ? 'Processing' : 'Completed'}
                        </span>
                    </div>
                </div>
                <div className="text-right">
                    <p className="font-bold text-gray-900">{donor.price?.toLocaleString()} DA</p>
                    <p className="text-xs text-gray-500">{new Date(donor.createdAt).toLocaleDateString()}</p>
                </div>
            </div>
        </div>
    );
};


export default DonorCard;
